1: /**
2:  * @NApiVersion 2.1
3:  * @NModuleScope SameAccount
4:  * @description Módulo centralizado para el cálculo matemático y validación jerárquica de márgenes comerciales.
5:  */
6: 
7: define(['N/error', 'N/log'], (error, log) => {
8: 
9:     /**
10:      * @typedef {Object} MarginParams
11:      * @property {number} precioBase - Precio unitario base de la línea.
12:      * @property {number} margenEstandar - Margen estándar en porcentaje decimal (ej. 0.20 para 20%).
13:      * @property {number} descMargenSolicitado - Descuento solicitado por el usuario.
14:      * @property {number} descMargenServicio - Descuento otorgado por nivel de servicio.
15:      * @property {number} limiteArticulo - Capacidad máxima de descuento del artículo.
16:      * @property {number} limiteCliente - Límite de descuento admitido para el cliente en la cabecera.
17:      * @property {number} limiteUsuario - Límite de descuento admitido por el rol/usuario.
18:      */
19: 
20:     /**
21:      * Procesa la lógica matemática de márgenes y evalúa las restricciones de negocio.
22:      * @param {MarginParams} params - Objeto contenedor de las variables necesarias para el cálculo.
23:      * @returns {{isValid: boolean, errorMessage: string, appliedMargin: number, finalPrice: number}}
24:      */
25:     const validateMarginRule = (params) => {
26:         const precioBase = parseFloat(params.precioBase) || 0;
27:         const margenEstandar = parseFloat(params.margenEstandar) || 0;
28:         const descMargenSolicitado = parseFloat(params.descMargenSolicitado) || 0;
29:         const descMargenServicio = parseFloat(params.descMargenServicio) || 0;
30:         const limiteArticulo = parseFloat(params.limiteArticulo) || 0;
31:         const limiteCliente = parseFloat(params.limiteCliente) || 0;
32:         const limiteUsuario = parseFloat(params.limiteUsuario) || 0;
33: 
34:         let isValid = true;
35:         let errorMessage = '';
36: 
37:         const limiteClienteReducido = limiteCliente * (1 - descMargenServicio);
38: 
39:         const costo = (precioBase * (100 - margenEstandar)) / 100;
40:         const margenAplicado = margenEstandar - (margenEstandar * descMargenSolicitado);
41: 
42:         if (descMargenSolicitado > limiteArticulo) {
43: 
44:             isValid = false;
45:             errorMessage = `Nivel 1: El descuento (${(descMargenSolicitado * 100).toFixed(2)}%) supera la capacidad máxima de este artículo.`;
46:         } else if (descMargenSolicitado > limiteClienteReducido) {
47:             isValid = false;
48:             errorMessage = `Nivel 2: El descuento supera el límite del cliente permitido por las condiciones de envío (${(limiteClienteReducido * 100).toFixed(2)}%).`;
49:         } else if (descMargenSolicitado > limiteUsuario) {
50:             isValid = false;
51:             errorMessage = `Nivel 3: El descuento (${(descMargenSolicitado * 100).toFixed(2)}%) supera tu límite de usuario.`;
52:         }
53: 
54:         if (!isValid) {
55:             log.audit({
56:                 title: 'Bloqueo en Sistema de Márgenes',
57:                 details: `Validación fallida. Razón: ${errorMessage} | Margen Calculado: ${margenAplicado.toFixed(4)} | Descuento Solicitado: ${descMargenSolicitado.toFixed(4)}`
58:             });
59:             return { isValid, errorMessage, appliedMargin: 0, finalPrice: precioBase };
60:         }
61: 
62: 
63:         if (margenAplicado <= 0) {
64:             throw error.create({
65:                 name: 'MATH_DIV_BY_ZERO_PREVENTION',
66:                 message: `Cálculo abortado. El margen aplicado resultó en ${margenAplicado}, lo que causaría una división por cero.`,
67:                 notifyOff: true
68:             });
69:         }
70: 
71:         let precioFinal = costo * (100 / (100 - margenAplicado));
72:         precioFinal = Math.round((precioFinal + Number.EPSILON) * 100) / 100;
73: 
74: 
75: 
76: 
77:         return {
78:             isValid,
79:             errorMessage,
80:             appliedMargin: margenAplicado,
81:             finalPrice: precioFinal
82:         };
83:     };
84: 
85:     return { validateMarginRule };
86: });

