1: /**
2:  * @NApiVersion 2.1
3:  * @NModuleScope SameAccount
4:  * @description Módulo centralizado para el cálculo de sobrecargos físicos por corte con regla de mínimo unitario.
5:  */
6: define([], () => {
7:     
8:     /**
9:      * Calcula el monto financiero del sobrecargo en base a las reglas físicas y comerciales.
10:      * @param {Object} params 
11:      * @returns {number} Monto exacto del sobrecargo unitario.
12:      */
13:     const calculateSurcharge = (params) => {
14:         const { precioBase, quantity, largoArticulo, solicitarCorte, aplicaSobreCargo, configSurcharge } = params;
15: 
16:         // Validaciones de seguridad de datos de línea
17:         if (!aplicaSobreCargo || !solicitarCorte || !largoArticulo || largoArticulo <= 0 || !quantity || quantity <= 0) {
18:             return 0;
19:         }
20: 
21:         const porcentajeUso = quantity / largoArticulo;
22:         let factorSobrecargo = 0;
23: 
24:         // Evaluación de rangos dinámicos
25:         if (porcentajeUso > 0 && porcentajeUso < 0.20) {
26:             factorSobrecargo = configSurcharge.rango1 || 0.20;
27:         } else if (porcentajeUso >= 0.20 && porcentajeUso < 0.40) {
28:             factorSobrecargo = configSurcharge.rango2 || 0.15;
29:         } else if (porcentajeUso >= 0.40 && porcentajeUso < 0.60) {
30:             factorSobrecargo = configSurcharge.rango3 || 0.10;
31:         } else if (porcentajeUso >= 0.60) {
32:             factorSobrecargo = configSurcharge.rango4 || 0.05;
33:         }
34: 
35:         // 1. Cálculo matemático inicial del sobrecargo por unidad
36:         let montoCargoExtra = (parseFloat(precioBase) * factorSobrecargo) || 0;
37: 
38:         // 2. NUEVA LÓGICA CONDICIONAL: Asegurar un cargo mínimo de 15 pesos por unidad
39:         if (montoCargoExtra > 0 && montoCargoExtra < 15) {
40:             montoCargoExtra = 15;
41:         }
42: 
43:         return montoCargoExtra;
44:     };
45: 
46:     return { calculateSurcharge };
47: });

