1: /**
2:  * @NApiVersion 2.1
3:  * @NScriptType ClientScript
4:  * @NModuleScope SameAccount
5:  * @description Controlador de interfaz de usuario para inyección de precios, estado global y validación de reglas en líneas.
6:  * @appliedtorecord - Estimate.
7:  * @author Saul Ivan Angulo Varela
8:  * @contact saul.angulo98@gmail.com
9:  * @version 1.0.0
10:  * @copyright Saul Angulo Development Services
11:  * @RiotID - ares98
12:  */
13: 
14: define(['N/ui/dialog', 'N/search', './CM_Margin_System_Core', './CM_Surcharge_System_Core'],
15:     (dialog, search, core, surchargeCore) => {
16: 
17:         // Estado global para cachear límites y controlar el flujo de la UI
18:         const globalState = {
19:             limiteCliente: 0,
20:             limiteUsuario: 0,
21:             reduccionServicioActual: 0,
22:             nivelesEnvio: { noEnvio: 0, envioHoy: 0, envioDias: 0 },
23:             isRecalculating: false,
24:             terminoEntregaAnterior: null,
25:             configSobrecargos: {}
26:         };
27: 
28:         /**
29:          * GATILLO 1: Inicialización de la página. Se lee el estado base inyectado por User Event.
30:          */
31:         const pageInit = (context) => {
32:             const rec = context.currentRecord;
33: 
34:             globalState.limiteUsuario = parseFloat(rec.getValue({ fieldId: 'custbody_curr_user_discount_limit' })) || 0;
35:             globalState.terminoEntregaAnterior = rec.getValue({ fieldId: 'custbody_freigth_service_terms' });
36:             globalState.limiteCliente = parseFloat(rec.getValue({ fieldId: 'custbody_curr_cust_discount_limit' })) || 0;
37:             globalState.reduccionServicioActual = parseFloat(rec.getValue({ fieldId: 'custbody_cust_serv_lvl' })) || 0;
38: 
39:             const customerId = rec.getValue({ fieldId: 'entity' });
40:             if (customerId) {
41:                 handleCustomerChange(rec);
42:             }
43:             
44:             const injectedConfig = rec.getValue({ fieldId: 'custbody_sang_hidden_surcharge_config' });
45:             if (injectedConfig) {
46:                 try {
47:                     globalState.configSobrecargos = JSON.parse(injectedConfig);
48:                 } catch (e) {
49:                     console.error('[CM_ERROR] No se pudo parsear la config de sobrecargos', e);
50:                 }
51:             }
52: 
53:             console.log('[CM_DEBUG] pageInit completado. Estado inicial:', JSON.stringify(globalState));
54:         };
55: 
56:         /**
57:          * GATILLO 2: Manejador central de cambios en cabecera y líneas.
58:          * EXCLUSIVO para interacciones manuales que NO requieren ir al servidor por datos maestros.
59:          */
60:         const fieldChanged = (context) => {
61:             const { currentRecord: rec, sublistId, fieldId } = context;
62: 
63:             if (fieldId === 'entity') {
64:                 handleCustomerChange(rec);
65:                 return;
66:             }
67: 
68:             if (fieldId === 'custbody_freigth_service_terms') {
69:                 handleTermsChange(rec);
70:                 return;
71:             }
72: 
73:             if (sublistId === 'item') {
74:                 // NUEVO: Agregamos quantity y sobre_cargo a los disparadores
75:                 const validTriggers = ['custcol_mergn_desc_solicitado', 'price', 'quantity', 'custcol_drt_sobre_cargo'];
76:                 if (validTriggers.includes(fieldId)) {
77:                     evaluateLineRules(rec, fieldId);
78:                 }
79:             }
80:         };
81: 
82:         /**
83:          * GATILLO 3: Ejecutado DESPUÉS de que NetSuite trae datos del servidor (Sourcing).
84:          * Arquitectura en Cascada: Dejamos que NetSuite termine de popular el Rate tras forzar el Nivel de Precio a 1.
85:          */
86:         const postSourcing = (context) => {
87:             const { currentRecord: rec, sublistId, fieldId } = context;
88: 
89:             if (sublistId !== 'item') return;
90: 
91:             // CASO A: Cambia el Artículo o la Unidad de Medida
92:             if (fieldId === 'item' || fieldId === 'units') {
93: 
94:                 try {
95:                     const idUnidadTransaccion = rec.getCurrentSublistValue({ sublistId: 'item', fieldId: 'units' });
96:                     const idUnidadBase = rec.getCurrentSublistValue({ sublistId: 'item', fieldId: 'custcol_drt_unidad_stock' });
97: 
98:                     // Extraemos el texto visible y lo pasamos a minúsculas para evitar errores de tipeo (ej. "M", "Mt")
99:                     const textoUnidad = (rec.getCurrentSublistText({ sublistId: 'item', fieldId: 'units' }) || '').toLowerCase();
100:                     const unidadesValidasParaCorte = ['m', 'mt', 'mts', 'm2'];
101: 
102:                     // Si las unidades son diferentes Y la nueva unidad es válida para cortes -> Encendemos el check
103:                     //console.log(`[CM_DEBUG-TRUE] Ud_Trans: '${textoUnidad}' Se activa sobrecargo - Ud_Values: ${idUnidadTransaccion} vs ${idUnidadBase}`);
104: 
105:                     if (idUnidadTransaccion && idUnidadBase && (idUnidadTransaccion !== idUnidadBase) && unidadesValidasParaCorte.includes(textoUnidad)) {
106:                         rec.setCurrentSublistValue({ sublistId: 'item', fieldId: 'custcol_drt_sobre_cargo', value: true, ignoreFieldChange: true });
107:                     } else {
108:                         rec.setCurrentSublistValue({ sublistId: 'item', fieldId: 'custcol_drt_sobre_cargo', value: false, ignoreFieldChange: true });
109:                     }
110:                 } catch (e) {
111:                     console.error('[CM_ERROR] Error en postSourcing durante evaluación de sobrecargo:', e);
112:                 }
113:                 try {
114:                     const currentPriceLvl = rec.getCurrentSublistValue({ sublistId: 'item', fieldId: 'price' });
115: 
116:                     // Si el precio está en Custom (-1) o cualquier otro, lo forzamos a Base (1)
117:                     if (currentPriceLvl != 1) {
118:                         console.log(`[CM_DEBUG] Forzando Nivel de Precio a 1 debido a cambio en ${fieldId}...`);
119:                         // Esto disparará una nueva llamada al servidor y volverá a entrar a postSourcing pero con fieldId === 'price'
120:                         rec.setCurrentSublistValue({ sublistId: 'item', fieldId: 'price', value: 1, ignoreFieldChange: false });
121:                         return; // Cortamos la ejecución aquí.
122:                     } else {
123:                         // Si ya estaba en 1, el rate es correcto. Procedemos a respaldar.
124:                         backupBasePrice(rec);
125:                         evaluateLineRules(rec, fieldId);
126:                     }
127:                 } catch (e) {
128:                     console.error('[CM_ERROR] Error en postSourcing durante backup de precio:', e);
129:                 }
130: 
131:             }
132: 
133:             // CASO B: Respondiendo al forzado de Precio a 1 (La "Luz Verde")
134:             else if (fieldId === 'price') {
135:                 const currentPriceLvl = rec.getCurrentSublistValue({ sublistId: 'item', fieldId: 'price' });
136: 
137:                 // Si NetSuite ya terminó de cargar el Nivel Base (1), ahora sí el Rate es 100% confiable
138:                 if (currentPriceLvl == 1) {
139:                     console.log('[CM_DEBUG] Sourcing de Precio terminado. Respaldando Rate...');
140:                     backupBasePrice(rec);
141:                     evaluateLineRules(rec, fieldId);
142:                 }
143:             }
144:         };
145: 
146:         /**
147:          * Función Auxiliar para limpiar descuentos y guardar el precio nativo de forma segura.
148:          */
149:         const backupBasePrice = (rec) => {
150:             globalState.isRecalculating = true; // Bloqueamos tus reglas de validación temporales
151:             try {
152:                 // Ahora este 'rate' es 100% el precio base de la nueva unidad o artículo
153:                 const precioNativoOriginal = parseFloat(rec.getCurrentSublistValue({ sublistId: 'item', fieldId: 'rate' })) || 0;
154: 
155:                 rec.setCurrentSublistValue({ sublistId: 'item', fieldId: 'custcol_mergn_desc_solicitado', value: '', ignoreFieldChange: true });
156:                 rec.setCurrentSublistValue({ sublistId: 'item', fieldId: 'custcol_margen_aplicado', value: '', ignoreFieldChange: true });
157:                 rec.setCurrentSublistValue({ sublistId: 'item', fieldId: 'custcol_precio_sin_margen', value: precioNativoOriginal, ignoreFieldChange: true });
158: 
159:                 console.log(`[CM_DEBUG] Línea reseteada. Nuevo Precio de Respaldo: ${precioNativoOriginal}`);
160:             } catch (e) {
161:                 console.error('[CM_ERROR] Falla durante el reseteo:', e);
162:             } finally {
163:                 globalState.isRecalculating = false;
164:             }
165:         };
166: 
167:         /**
168:          * GATILLO 4: Bloqueo final antes de permitir que la línea ingrese al sistema.
169:          */
170:         const validateLine = (context) => {
171:             const { currentRecord: rec, sublistId } = context;
172: 
173:             if (sublistId !== 'item') return true;
174: 
175:             // Silenciar bloqueos durante el auto-ajuste iterativo
176:             if (globalState.isRecalculating) return true;
177: 
178:             const itemType = rec.getCurrentSublistValue({ sublistId: 'item', fieldId: 'itemtype' });
179:             const descSolicitado = parseFloat(rec.getCurrentSublistValue({ sublistId: 'item', fieldId: 'custcol_mergn_desc_solicitado' })) || 0;
180: 
181:             if (itemType === 'Group' || itemType === 'Kit' || itemType === 'EndGroup' || descSolicitado === 0) {
182:                 return true;
183:             }
184: 
185:             const params = {
186:                 precioBase: parseFloat(rec.getCurrentSublistValue({ sublistId: 'item', fieldId: 'rate' })) || 0,
187:                 margenEstandar: parseFloat(rec.getCurrentSublistValue({ sublistId: 'item', fieldId: 'custcol_margen_estandar' })) || 0,
188:                 descMargenSolicitado: descSolicitado / 100,
189:                 descMargenServicio: globalState.reduccionServicioActual / 100,
190:                 limiteArticulo: (parseFloat(rec.getCurrentSublistValue({ sublistId: 'item', fieldId: 'custcol_maxdiscount_margin_percent' })) || 0) / 100,
191:                 limiteCliente: globalState.limiteCliente / 100,
192:                 limiteUsuario: globalState.limiteUsuario / 100
193:             };
194: 
195:             const result = core.validateMarginRule(params);
196:             
197: 
198:             if (!result.isValid) {
199:                 dialog.alert({
200:                     title: 'Restricción de Margen Comercial',
201:                     message: result.errorMessage
202:                 });
203:                 return false;
204:             
205:             }
206: 
207:             return true;
208:         };
209: 
210:         // ========================================================================
211:         // FUNCIONES AUXILIARES (HELPERS)
212:         // ========================================================================
213: 
214:         const handleCustomerChange = (rec) => {
215:             const customerId = rec.getValue({ fieldId: 'entity' });
216:             if (!customerId) {
217:                 globalState.limiteCliente = 0;
218:                 globalState.nivelesEnvio = { noEnvio: 0, envioHoy: 0, envioDias: 0 };
219:                 return;
220:             }
221: 
222:             const termsField = rec.getField({ fieldId: 'custbody_freigth_service_terms' });
223:             if (termsField) termsField.isDisabled = true;
224: 
225:             search.lookupFields.promise({
226:                 type: search.Type.CUSTOMER,
227:                 id: customerId,
228:                 columns: [
229:                     'custentity_maxdiscount_margin_percent',
230:                     'custentity_custrec_service_level'
231:                 ]
232:             }).then((customerData) => {
233:                 globalState.limiteCliente = parseFloat(customerData.custentity_maxdiscount_margin_percent) || 0;
234:                 rec.setValue({ fieldId: 'custbody_curr_cust_discount_limit', value: globalState.limiteCliente });
235: 
236:                 const serviceLevelField = customerData.custentity_custrec_service_level;
237:                 const serviceLevelId = (serviceLevelField && serviceLevelField.length > 0)
238:                     ? serviceLevelField[0].value
239:                     : null;
240: 
241:                 if (!serviceLevelId) {
242:                     globalState.nivelesEnvio = { noEnvio: 0, envioHoy: 0, envioDias: 0 };
243:                     console.log('[CM_DEBUG] Cliente sin Nivel de Servicio asignado. Límite de cliente:', globalState.limiteCliente);
244:                     if (termsField) termsField.isDisabled = false;
245:                     return Promise.reject('NO_SERVICE_LEVEL');
246:                 }
247:                 rec.setValue({ fieldId: 'custbody_customer_level_service_rec', value: serviceLevelId });
248: 
249:                 return search.lookupFields.promise({
250:                     type: 'customrecord_margin_system_lvl_service',
251:                     id: serviceLevelId,
252:                     columns: ['custrecord_serv_lvl_noenvio', 'custrecord_serv_lvl_enviohoy', 'custrecord_serv_lvl_enviodias']
253:                 });
254: 
255:             }).then((serviceData) => {
256:                 if (serviceData) {
257:                     globalState.nivelesEnvio = {
258:                         noEnvio: parseFloat(serviceData.custrecord_serv_lvl_noenvio) || 0,
259:                         envioHoy: parseFloat(serviceData.custrecord_serv_lvl_enviohoy) || 0,
260:                         envioDias: parseFloat(serviceData.custrecord_serv_lvl_enviodias) || 0
261:                     };
262:                     console.log('[CM_DEBUG] Promesas resueltas. Límite Cliente:', globalState.limiteCliente, '| Niveles:', globalState.nivelesEnvio);
263:                 }
264:                 if (termsField) termsField.isDisabled = false;
265: 
266:             }).catch((e) => {
267:                 if (e !== 'NO_SERVICE_LEVEL') {
268:                     console.error('Error obteniendo datos del cliente/servicio:', e);
269:                 }
270:                 if (termsField) termsField.isDisabled = false;
271:             });
272:         };
273: 
274:         const handleTermsChange = (rec) => {
275:             console.log('[CM_DEBUG] Cambio detectado en término de entrega. Evaluando impacto...');
276:             const terminoSeleccionado = rec.getValue({ fieldId: 'custbody_freigth_service_terms' });
277:             let nuevaReduccion = 0;
278: 
279:             if (terminoSeleccionado === '1') {
280:                 nuevaReduccion = globalState.nivelesEnvio.envioHoy;
281:             } else if (terminoSeleccionado === '2') {
282:                 nuevaReduccion = globalState.nivelesEnvio.noEnvio;
283:             } else if (terminoSeleccionado === '3') {
284:                 nuevaReduccion = globalState.nivelesEnvio.envioDias;
285:             }
286: 
287:             const lineCount = rec.getLineCount({ sublistId: 'item' });
288: 
289:             if (nuevaReduccion > globalState.reduccionServicioActual && lineCount > 0) {
290:                 console.log(`[CM_DEBUG] Entrada al bloque de recálculo. Reducción vieja: ${globalState.reduccionServicioActual} | Nueva: ${nuevaReduccion}`);
291: 
292:                 dialog.confirm({
293:                     title: 'Cambio de Condiciones',
294:                     message: 'Este término reduce la capacidad de descuento. Los precios se recalcularán al nuevo límite permitido. ¿Desea continuar?'
295:                 }).then((success) => {
296:                     if (success) {
297:                         processLineRecalculation(rec, nuevaReduccion, terminoSeleccionado, lineCount);
298:                     } else {
299:                         setTimeout(() => {
300:                             rec.setValue({
301:                                 fieldId: 'custbody_termino_entrega',
302:                                 value: globalState.terminoEntregaAnterior,
303:                                 ignoreFieldChange: true
304:                             });
305:                             console.log('[CM_DEBUG] Rollback de término de entrega ejecutado vía setTimeout.');
306:                         }, 0);
307:                     }
308:                 });
309:             }
310:             else {
311:                 globalState.reduccionServicioActual = nuevaReduccion;
312:                 globalState.terminoEntregaAnterior = terminoSeleccionado;
313:                 rec.setValue({ fieldId: 'custbody_cust_serv_lvl', value: globalState.reduccionServicioActual, ignoreFieldChange: true });
314:             }
315:         };
316: 
317:         const processLineRecalculation = (rec, nuevaReduccion, nuevoTermino, lineCount) => {
318:             globalState.isRecalculating = true;
319:             globalState.reduccionServicioActual = nuevaReduccion;
320:             globalState.terminoEntregaAnterior = nuevoTermino;
321: 
322:             rec.setValue({ fieldId: 'custbody_cust_serv_lvl', value: globalState.reduccionServicioActual, ignoreFieldChange: true });
